def gen(rng):
    import string
    pool = string.ascii_letters + string.digits + '!#$%&()*+,-./:;<=>?@[]^_{|}~'
    def rs(n):
        return ''.join(rng.choice(pool) for _ in range(n))
    tests = ['a', 'ab', 'abc', 'aa', 'racecar', 'abba', '12345', '!@#', 'a1-b2', 'Zz']
    for n in range(3, 25):
        tests.append(rs(n))
    for n in (50, 100, 200, 300):
        tests.append(rs(n))
    tests.append(''.join(rng.choices(pool, k=10**6)))
    tests.append(''.join(rng.choices(pool, k=999999)))
    tests.append('a' * (10**6))
    tests.append('ab' * 500000)
    return tests

